from pathlib import Path
import re
p=Path('caso001-rev01/index.html')
s=p.read_text()
if 'P2.12D.7 · PRIVATE CHARACTER DOSSIER' in s:
    raise SystemExit('D7 already applied')

css=r'''
/* P2.12D.7 · PRIVATE CHARACTER DOSSIER */
.privateDossierPanel{padding:0;overflow:hidden;border-color:#62492f}.privatePanelHead{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:13px 15px;border-bottom:1px solid #4b3827;background:#100e0c}.privatePanelHead small{font-size:8px;letter-spacing:.17em;color:#9a866d;font-weight:900}.privatePanelHead b{display:block;margin-top:3px;font:700 17px/1.1 Georgia,serif;color:#eadac6}.privacyToggle{border:1px solid #6d5135;background:#1a140f;color:#d9b879;padding:7px 9px;border-radius:4px;font-size:8px;letter-spacing:.09em;font-weight:900;cursor:pointer}.privacyToggle:hover{border-color:#a97d45}.privateDossier{position:relative}.privateHero{display:grid;grid-template-columns:132px 1fr;min-height:178px;background:linear-gradient(135deg,#19140f,#0c0b0a);border-bottom:1px solid #503a27}.privatePortrait{position:relative;overflow:hidden;background:#0c0b0a;border-right:1px solid #594129}.privatePortrait img{width:100%;height:100%;object-fit:cover;object-position:center 22%;display:block;filter:saturate(.86) contrast(1.05)}.privatePortrait:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 52%,rgba(0,0,0,.75)),repeating-linear-gradient(0deg,transparent 0 3px,rgba(255,255,255,.018) 3px 4px)}.privatePortraitTag{position:absolute;left:7px;bottom:7px;z-index:2;background:#0a0806dd;border:1px solid #765b3d;color:#dbc28f;padding:4px 6px;font-size:7px;letter-spacing:.1em;font-weight:900}.privateIdentity{padding:16px 15px;display:flex;flex-direction:column;justify-content:center;position:relative}.privateIdentity:after{content:"SOLO VOS";position:absolute;right:10px;top:10px;border:2px solid rgba(154,41,36,.48);color:rgba(210,79,68,.62);padding:4px 7px;transform:rotate(-5deg);font-size:8px;letter-spacing:.13em;font-weight:950}.privateEyebrow{font-size:7px;letter-spacing:.16em;color:#88765f;font-weight:900}.privateIdentity h3{font-family:Georgia,serif;font-size:27px;margin:5px 0 4px;color:#f0e2d1}.privateProfile{color:#bda88f;font-size:11px}.privateRoleBadge{margin-top:12px;display:inline-flex;align-self:flex-start;border:1px solid #6f542f;background:#1b150e;color:#e5bd73;padding:6px 8px;font-size:8px;letter-spacing:.12em;font-weight:950}.privateRoleBadge.killer{border-color:#873b3c;background:#261215;color:#f0aaa7}.privateSensitive{padding:14px 15px 2px}.privateObjective{border-left:4px solid #a37841;background:#17130f;padding:11px 12px}.privateObjective small{display:block;color:#9a815f;font-size:7px;letter-spacing:.13em;font-weight:950;margin-bottom:5px}.privateObjective p{margin:0;color:#ddd0bf;font-size:12px;line-height:1.5}.classifiedPocket{margin-top:12px;border:1px solid #6c3435;background:linear-gradient(135deg,#261417,#130e10);padding:12px;position:relative;overflow:hidden}.classifiedPocket:after{content:"CLASIFICADO";position:absolute;right:-12px;bottom:10px;border:2px solid rgba(194,68,63,.28);color:rgba(216,83,76,.38);padding:4px 10px;transform:rotate(-7deg);font-weight:950;letter-spacing:.14em;font-size:9px}.classifiedPocket b{color:#e4aaa7;font-size:9px;letter-spacing:.1em}.classifiedPocket p{font-size:11px;line-height:1.48;color:#d9c1bf;margin:7px 0}.privateEvidenceWrap{padding:0 15px 15px}.privacyCover{margin:14px 15px 15px;min-height:150px;border:1px dashed #6d5338;background:repeating-linear-gradient(135deg,#100e0b 0 9px,#15110d 9px 18px);display:grid;place-items:center;text-align:center;padding:22px}.privacyCover b{display:block;color:#d6ad68;font:700 18px Georgia,serif;margin-bottom:6px}.privacyCover span{color:#8e7b65;font-size:10px;line-height:1.5}.privateHidden{display:none!important}.privateEmpty{padding:13px 15px 16px}.privateIdentityMeta{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.privateIdentityMeta span{font-size:7px;letter-spacing:.08em;border:1px solid #4e3d2d;padding:4px 5px;color:#8f7e6b}.privateDossier .evidenceStage{margin-top:13px}
@media(max-width:720px){.privateHero{grid-template-columns:112px 1fr}.privateIdentity h3{font-size:23px}.privatePanelHead{align-items:flex-start}.privacyToggle{max-width:135px}.privatePortrait{min-height:165px}}
@media(max-width:420px){.privateHero{grid-template-columns:96px 1fr}.privateIdentity{padding:13px 11px}.privateIdentity h3{font-size:20px}.privateIdentity:after{font-size:6px;right:5px;top:6px}.privateProfile{font-size:9px}.privateSensitive,.privateEvidenceWrap{padding-left:11px;padding-right:11px}}
'''
anchor='/* P2.12D.6 · EVIDENCE RENDERER */'
if anchor not in s: raise SystemExit('D6 marker missing')
s=s.replace(anchor,css+'\n'+anchor,1)

old='''      <section class="panel"><h2 style="margin-top:0">Tu información</h2><div id="roleBox"></div><div id="privateEvidence"></div></section>'''
new='''      <section class="panel privateDossierPanel"><div class="privatePanelHead"><div><small>EXPEDIENTES · CASO 001</small><b>Dossier privado</b></div><button id="privacyToggle" class="privacyToggle" type="button">OCULTAR INFORMACIÓN</button></div><div id="roleBox"></div><div id="privatePrivacyCover" class="privacyCover hidden"><div><b>Información privada oculta</b><span>Volvé a mostrarla cuando nadie más esté mirando la pantalla.</span></div></div><div id="privateEvidence" class="privateEvidenceWrap"></div></section>'''
if old not in s: raise SystemExit('private panel html anchor missing')
s=s.replace(old,new,1)

state="let entryMode='create',selectedCharacter=0,view=null,privateView=null,refreshing=false,pendingRefresh=false,tickTimer=null,clockTimer=null,busy=false;"
if state not in s: raise SystemExit('state anchor missing')
s=s.replace(state,state+"\nlet privateInfoHidden=false;",1)

helpers=r'''function privateCharacterIndex(){const candidates=[privateView?.character_index,privateView?.player?.character_index,privateView?.character?.index,view?.me?.character_index,view?.current_player?.character_index];const uid=adapter.user?.id;if(uid){const me=(view?.players||[]).find(p=>p.user_id===uid||p.userId===uid||p.auth_user_id===uid||p.is_me===true||p.me===true);if(me)candidates.unshift(me.character_index)}for(const value of candidates){const n=Number(value);if(Number.isInteger(n)&&n>=0&&n<6)return n}const fallback=Number(selectedCharacter);return Number.isInteger(fallback)&&fallback>=0&&fallback<6?fallback:0}
function privatePlayerName(index){const p=(view?.players||[]).find(x=>Number(x.character_index)===Number(index));return String(p?.display_name||'Investigador')}
function applyPrivateVisibility(){const sensitive=$('#privateSensitive'),evidence=$('#privateEvidence'),cover=$('#privatePrivacyCover'),button=$('#privacyToggle');sensitive?.classList.toggle('privateHidden',privateInfoHidden);evidence?.classList.toggle('privateHidden',privateInfoHidden);cover?.classList.toggle('hidden',!privateInfoHidden);if(button)button.textContent=privateInfoHidden?'MOSTRAR INFORMACIÓN':'OCULTAR INFORMACIÓN'}
'''

pat=re.compile(r'function renderPrivate\(\)\{.*?\}\nfunction renderTimeline\(\)\{',re.S)
m=pat.search(s)
if not m: raise SystemExit('renderPrivate anchor missing')
new_private=r'''function renderPrivate(){if(!privateView){$('#roleBox').innerHTML='<div class="privateEmpty empty">La información privada aparecerá cuando comience la partida.</div>';$('#privateEvidence').innerHTML='';$('#privatePrivacyCover').classList.add('hidden');return}const r=privateView.role_payload||{},killer=privateView.role==='killer',idx=privateCharacterIndex(),name=P2_LABELS.characters[idx]||'Investigador',profile=REV01_PROFILES[idx]||'Persona vinculada al caso',portrait=REV01_PORTRAITS[idx],playerName=privatePlayerName(idx),roleLabel=r.role_label||'INVESTIGADOR';$('#roleBox').innerHTML=`<article class="privateDossier"><div class="privateHero"><div class="privatePortrait"><img src="${esc(portrait)}" alt="Retrato de ${esc(name)}"><span class="privatePortraitTag">PERSONA ${String(idx+1).padStart(2,'0')}</span></div><div class="privateIdentity"><div class="privateEyebrow">IDENTIDAD ASIGNADA · LECTURA PRIVADA</div><h3>${esc(name)}</h3><div class="privateProfile">${esc(profile)}</div><div class="privateIdentityMeta"><span>${esc(playerName)}</span><span>${esc(P2_LABELS.characterIds[idx]||'PERSONA')}</span></div><span class="privateRoleBadge ${killer?'killer':''}">${esc(roleLabel)}</span></div></div><div id="privateSensitive" class="privateSensitive"><div class="privateObjective"><small>OBJETIVO PRIVADO</small><p>${esc(r.objective||'Analizá las evidencias, cruzá contradicciones y ayudá al equipo a reconstruir el caso.')}</p></div>${killer&&privateView.impostor_truth?`<div class="classifiedPocket"><b>ARCHIVO CLASIFICADO · SOLO VOS</b><p><strong>Mentira central:</strong> ${esc(privateView.impostor_truth.central_lie||'')}</p><p><strong>Hecho real:</strong> ${esc(privateView.impostor_truth.critical_event||'')}</p><p><strong>Encubrimiento:</strong> ${esc(privateView.impostor_truth.post_crime_action||'')}</p>${(r.allowed_powers||[]).length?`<p><strong>Recursos:</strong> ${esc((r.allowed_powers||[]).join(' · '))} · ${Number(r.sabotage_tokens||0)} ficha${Number(r.sabotage_tokens||0)===1?'':'s'}</p>`:''}</div>`:''}</div></article>`;const xs=privateView.private_evidence||[];$('#privateEvidence').innerHTML=xs.length?`<div class="evidenceStage"><b>EVIDENCIA SOLO PARA VOS</b><span>${xs.length} REGISTRO${xs.length===1?'':'S'}</span></div>`+xs.map((e,i)=>renderEvidenceCard(e,{privateCard:true,seq:i+1})).join(''):'<div class="privateEmpty empty">No tenés evidencia privada liberada en esta etapa.</div>';applyPrivateVisibility()}
'''
s=s[:m.start()]+helpers+new_private+'function renderTimeline(){'+s[m.end():]

hook="$('#tabCreate').onclick=()=>setEntryMode('create');$('#tabJoin').onclick=()=>setEntryMode('join');$('#enterRoom').onclick=enter;$('#rejoinLast').onclick=rejoin;"
if hook not in s: raise SystemExit('event hook anchor missing')
s=s.replace(hook,hook+"\n$('#privacyToggle').onclick=()=>{privateInfoHidden=!privateInfoHidden;applyPrivateVisibility()};",1)

p.write_text(s)
print('P2.12D.7 patch complete')
